const { exec } = require("child_process");

// Count lines in a file.
function countLines(path, cb) {
  exec("wc -l " + path, (err, stdout) => cb(stdout));
}

module.exports = { countLines };

'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const { countLines } = require('../src/cmd');

test('counts_lines', (done) => {
  const file = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'cmd-')), 'a.txt');
  fs.writeFileSync(file, 'one\ntwo\n');
  countLines(file, (stdout) => {
    expect(stdout.trim().startsWith('2')).toBe(true);
    done();
  });
});
